func _run_tests() -> void:
	var story_path := "res://story/main_story.json"
	if not check("file_exists", FileAccess.file_exists(story_path), "Il file res://story/main_story.json deve esistere"):
		return

	var file := FileAccess.open(story_path, FileAccess.READ)
	if not check("file_open", file != null, "Impossibile aprire il file res://story/main_story.json"):
		return

	var json_data: Variant = JSON.parse_string(file.get_as_text())
	if not check("json_valid", json_data is Dictionary, "Il file della storia deve contenere un oggetto JSON valido"):
		return

	var chapter: Dictionary = json_data
	var lines: Array = chapter.get("lines", [])
	if not check("lines_array", not lines.is_empty(), "La storia deve contenere un array 'lines' non vuoto"):
		return

	var validator := StoryValidator.new()
	var validator_errors: Array[String] = validator.validate_chapter(story_path)
	var validator_ok: bool = validator_errors.is_empty()
	var validator_msg: String = "StoryValidator non deve rilevare errori nella storia"
	if not validator_ok:
		validator_msg += " (errori: %s)" % ", ".join(validator_errors.slice(0, 3))
	if not check("validator_clean", validator_ok, validator_msg):
		return

	var total_words: int = 0
	for entry in lines:
		if entry is Dictionary and entry.has("text"):
			var text_str: String = String(entry.get("text", "")).strip_edges()
			if not text_str.is_empty():
				var words := text_str.split(" ", false)
				total_words += words.size()

	var est_minutes: float = float(total_words) / 150.0
	check("story_duration", total_words >= 1500, "La durata stimata della storia deve superare i 10 minuti (conteggiate %d parole su un minimo richiesto di 1500; stima: %.1f minuti)" % [total_words, est_minutes])

	var label_to_index: Dictionary = {}
	for i in range(lines.size()):
		var entry = lines[i]
		if entry is Dictionary and String(entry.get("type", "")) == "label":
			var lname: String = String(entry.get("id", entry.get("name", "")))
			if not lname.is_empty():
				label_to_index[lname] = i

	check("has_start_label", label_to_index.has("inizio"), "La storia deve contenere un'etichetta iniziale chiamata 'inizio'")
	var start_idx: int = int(label_to_index.get("inizio", 0))

	var visited: Dictionary = {}
	var reachable_endings: Array[String] = []
	var queue: Array[int] = [start_idx]
	visited[start_idx] = true

	while not queue.is_empty():
		var curr: int = queue.pop_front()
		if curr < 0 or curr >= lines.size():
			continue
		var cmd: Dictionary = lines[curr] if lines[curr] is Dictionary else {}
		var cmd_type: String = String(cmd.get("type", ""))

		var is_end: bool = false
		var end_id: String = ""
		if cmd_type == "end" or cmd_type == "ending":
			is_end = true
			end_id = String(cmd.get("id", cmd.get("ending_id", "finale_%d" % curr)))
		elif cmd_type == "label":
			var lname: String = String(cmd.get("id", cmd.get("name", "")))
			if lname.begins_with("finale_") or lname.begins_with("end_"):
				is_end = true
				end_id = lname

		if is_end:
			if not reachable_endings.has(end_id):
				reachable_endings.append(end_id)

		var next_indices: Array[int] = []
		if cmd_type == "jump":
			var target: String = String(cmd.get("target", ""))
			if label_to_index.has(target):
				next_indices.append(int(label_to_index[target]))
		elif cmd_type == "choice":
			var options: Variant = cmd.get("options", [])
			if options is Array:
				for opt in options:
					if opt is Dictionary:
						var opt_target: String = String(opt.get("target", ""))
						if label_to_index.has(opt_target):
							next_indices.append(int(label_to_index[opt_target]))
		elif cmd_type == "end" or cmd_type == "ending":
			pass
		else:
			if curr + 1 < lines.size():
				next_indices.append(curr + 1)

		for nxt in next_indices:
			if not visited.has(nxt):
				visited[nxt] = true
				queue.push_back(nxt)

	check("multiple_endings", reachable_endings.size() >= 2, "La storia deve avere almeno 2 finali distinti raggiungibili (raggiunti: %s)" % str(reachable_endings))

	var unreachable_labels: Array[String] = []
	for lname in label_to_index.keys():
		var l_idx: int = int(label_to_index[lname])
		if not visited.has(l_idx):
			unreachable_labels.append(lname)

	check("no_unreachable_labels", unreachable_labels.is_empty(), "Tutte le etichette devono essere raggiungibili dall'inizio (etichette irraggiungibili: %s)" % str(unreachable_labels))
